async function main() {
  let count = 0;
  for (const d of data) {
    await p.question.update({
      where: { id: d.id },
      data: { question_fr: d.q, explanation_fr: d.e, options_fr: JSON.stringify(d.o) }
    });
    count++;
    if (count % 10 === 0) console.log(`✅ ${count}/${data.length} questions traduites`);
  }
  console.log(`✅ Terminé : ${count} questions traduites`);
  await p.$disconnect();
}

main().catch(e => { console.error('ERREUR:', e); p.$disconnect(); });
